<section class="surface mt-4"><h2 class="h4">Histórico do relato</h2><ol class="timeline"><?php foreach ($history as $h): ?><li><strong><?= e(status_label($h['status_novo'])) ?></strong><small><?= e(datebr($h['criado_em'])) ?></small><p><?= e($h['justificativa']) ?></p></li><?php endforeach ?></ol></section></div>
