<?php if ($row['status']!=='RESOLVIDA'): ?><details class="mt-3"><summary>Sugerir resolução</summary><form method="post" action="<?= e(url('/participar')) ?>" class="form-stack mt-3"><?= csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label for="resolucao">O que mudou?</label><textarea class="form-control" id="resolucao" name="descricao" minlength="10" maxlength="2000" required></textarea><button class="btn btn-outline-primary" name="acao" value="resolver">Enviar para análise</button></form></details><?php endif ?>
<?php else: ?><a href="<?= e(url('/entrar')) ?>">Entre para participar</a><?php endif ?><?php endif ?></section></aside></div>
