<?php if ($similar): ?><div class="alert alert-info">Possíveis duplicidades (mesma categoria, até 300 m e últimos 30 dias):<ul><?php foreach ($similar as $s): ?><li><a href="<?= e(url('/ocorrencia',['id'=>$s['id']])) ?>">#<?= (int)$s['id'] ?> — <?= e($s['titulo']) ?></a></li><?php endforeach ?></ul></div><?php endif ?>
<?php $next=\App\Services\OccurrenceState::TRANSITIONS[$row['status']]; if ($next && $row['status']!=='CORRECAO_SOLICITADA'): ?><form action="<?= e(url('/admin/moderar')) ?>" method="post" class="form-stack"><?= csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div><label for="situacao" class="form-label">Nova situação</label><select class="form-select" id="situacao" name="situacao"><?php foreach ($next as $s): ?><option value="<?= e($s) ?>"><?= e(status_label($s)) ?></option><?php endforeach ?></select></div><div><label for="principal_id" class="form-label">ID da ocorrência principal (obrigatório para duplicidade)</label><input type="number" min="1" class="form-control" id="principal_id" name="principal_id"></div><div><label for="justificativa" class="form-label">Justificativa</label><textarea class="form-control" name="justificativa" id="justificativa" minlength="5" maxlength="2000" required></textarea></div><button class="btn btn-primary align-self-start">Registrar alteração</button></form><?php else: ?><p>Não há transição administrativa disponível nesta situação.</p><?php endif ?></section><?php endif ?>
